-- Phase 6 dbt warehouse permissions, managed as a reviewed SQL migration.
-- Execute with a SQL administrator only AFTER a successful ECS dbt
-- --action auth-check. The first IAM login creates the exact IAMR identity.
-- Repeatable CREATE SCHEMA / GRANT operations; never modifies Silver data.
--
-- IAM principal (created by Terraform):
--   arn:aws:iam::825414820081:role/ecommerce-phase6-dbt-task-demo
-- SQL principal (generated by Redshift Serverless after IAM authentication):
--   "IAMR:ecommerce-phase6-dbt-task-demo"
--
-- This script assumes default environment=demo, database=analytics.
-- It is deliberately NOT executed from Terraform or on every dbt run:
-- SQL privilege changes need one controlled administrator migration.

CREATE SCHEMA IF NOT EXISTS analytics_staging;
CREATE SCHEMA IF NOT EXISTS analytics_marts;

-- Base target schema in profiles.yml is "analytics". Keep the base schema
-- available to dbt; custom model schemas resolve to analytics_staging/marts.
CREATE SCHEMA IF NOT EXISTS analytics;

-- Read-only access to the validated Silver sources.
GRANT USAGE ON SCHEMA silver_staging TO "IAMR:ecommerce-phase6-dbt-task-demo";
GRANT SELECT ON ALL TABLES IN SCHEMA silver_staging TO "IAMR:ecommerce-phase6-dbt-task-demo";

-- Only the dbt-owned staging and mart schemas are writable.
GRANT USAGE ON SCHEMA analytics TO "IAMR:ecommerce-phase6-dbt-task-demo";
GRANT USAGE, CREATE ON SCHEMA analytics_staging TO "IAMR:ecommerce-phase6-dbt-task-demo";
GRANT USAGE, CREATE ON SCHEMA analytics_marts TO "IAMR:ecommerce-phase6-dbt-task-demo";

-- No PUBLIC grants, no RDS privileges, no Redshift S3 COPY permissions.
-- Apply again after introducing a new Silver source table (or add a
-- carefully reviewed source-owner default-privileges policy).
